export const OPEN_PRESET = 'create-open-preset';
export const RESET = 'create-reset';
export const ACTION_MENU = 'create-action-menu';
export { GET_CODE } from './create-messages.ts';

export const themeOf = (name: string) => THEMES.find((t) => t.name === name);
export const isBaseColor = (name: string) => BASE_COLORS.some((b) => b.name === name);
export const dotOf = (name: string, baseColorKey: boolean): string => {
	const vars = themeOf(name)?.cssVars?.dark as Record<string, string> | undefined;
	return `--color: ${vars?.[baseColorKey || isBaseColor(name) ? 'muted-foreground' : 'primary'] ?? ''};`;
};
export const radiusLocked = (style: string) => style === 'lyra' || style === 'sera';
/** The value a radio item stands checked against: the radius Lyra and Sera lock to none. */
export const checkedValue = (params: CreateParams, param: string): string => (param === 'radius' && radiusLocked(params.style) ? 'none' : String(params[param as keyof CreateParams]));

export const menuColorOf = (color: string, translucent: boolean): string => (color === 'default' ? (translucent ? 'default-translucent' : 'default') : translucent ? 'inverted-translucent' : 'inverted');

export const menuColorChoice = (menuColor: string): string => (menuColor === 'inverted' || menuColor === 'inverted-translucent' ? 'inverted' : 'default');

/** setColor and setSurface (and their hover previews): the menu color they make, the accent moving with it. */
export function menuColorUpdate(params: CreateParams, solidAccent: string, axis: string, value: string): CreateUpdate {
	const translucent = isTranslucentMenuColor(params.menuColor);
	if (axis === 'color') {
		const next = menuColorOf(value, translucent);
		return { menuColor: next, ...(isTranslucentMenuColor(next) && { menuAccent: 'subtle' }) };
	}
	return { menuColor: menuColorOf(menuColorChoice(params.menuColor), value === 'translucent'), menuAccent: value === 'translucent' ? 'subtle' : solidAccent };
}

export const paramOf = (params: CreateParams, param: string): string => String(params[param as keyof CreateParams]);

let copyTimer: ReturnType<typeof setTimeout> | undefined;
/** The copied mark's two seconds, started again by each copy (CopyPreset's and ProjectForm's effect). */
export function afterCopy(reset: () => void): void {
	clearTimeout(copyTimer);
	copyTimer = setTimeout(reset, 2000);
}

